import itertools


class ArrangementCalculator:
    FULL_ARRANGEMENT_MULTIPLE = 1

    def __init__(self, datas):
        self._datas = list(datas)

    @staticmethod
    def count(n, m=None):
        if m is None or n == m:
            return ArrangementCalculator.factorial(n)
        return ArrangementCalculator.factorial(n) // ArrangementCalculator.factorial(n - m)

    @staticmethod
    def count_all(n):
        return sum(ArrangementCalculator.count(n, i) for i in range(1, n + 1))

    @property
    def datas(self):
        return list(self._datas)

    @datas.setter
    def datas(self, value):
        self._datas = list(value)

    def select(self, m=None):
        if m is None:
            m = len(self._datas)
        return self._generate_permutations(m)

    def select_all(self):
        return self._generate_all_permutations()

    def _generate_permutations(self, m):
        return [list(permutation) for permutation in itertools.permutations(self._datas, m)]

    def _generate_all_permutations(self):
        return [
            permutation
            for i in range(1, len(self._datas) + 1)
            for permutation in self._generate_permutations(i)
        ]

    @staticmethod
    def factorial(n):
        return ArrangementCalculator._compute_factorial(n)

    @staticmethod
    def _compute_factorial(n):
        return 1 if n <= 1 else n * ArrangementCalculator._compute_factorial(n - 1)
